/* Offline files are generated by build.py; updates wait for existing game tabs to close. */
importScripts('./offline-assets.js');
const ROOT=new URL('./',self.location.href),PREFIX='skyline-estates-offline:'+ROOT.href+':';
const CACHE=PREFIX+self.SKYLINE_OFFLINE.version,SHELL=new URL('index.html',ROOT).href;
const FILES=self.SKYLINE_OFFLINE.files.map(file=>new URL(file,ROOT).href),ALLOWED=new Set(FILES);
self.addEventListener('install',event=>event.waitUntil((async()=>{
  const cache=await caches.open(CACHE);
  try{await cache.addAll(FILES.map(url=>new Request(url,{cache:'reload'})))}catch(error){await caches.delete(CACHE);throw error}
  // Do not skipWaiting: a new version must not replace a running game.
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
  for(const name of await caches.keys())if(name.startsWith(PREFIX)&&name!==CACHE)await caches.delete(name);
  await self.clients.claim();
})()));
self.addEventListener('fetch',event=>{
  const request=event.request,url=new URL(request.url);
  if(request.method!=='GET'||url.origin!==ROOT.origin||!url.pathname.startsWith(ROOT.pathname))return;
  const home=request.mode==='navigate'&&(url.pathname===ROOT.pathname||url.pathname===new URL('index.html',ROOT).pathname);
  // Ignore room/API traffic, writes, neighbouring apps and arbitrary query responses.
  if(!home&&(url.search||!ALLOWED.has(url.href)))return;
  event.respondWith((async()=>{
    let cache,cached;const key=home?SHELL:request.url;
    try{cache=await caches.open(CACHE);cached=await cache.match(key)}catch(error){return fetch(request)}
    if(cached)return cached;
    const response=await fetch(request);
    if(response.ok&&(!home||!url.search))try{await cache.put(key,response.clone())}catch(error){console.warn('Offline cache storage unavailable')}
    return response;
  })());
});
